-- 90-Day Gameplan: Nov 8, 2026 to Feb 5, 2027: models part 1 of 4
-- Run in the MAISON DE VEUX Supabase project (SQL Editor). Safe to run again: every row made by this plan has a key
-- (metadata.gp_key), so a second run updates dates and text and never duplicates or resets a status.
-- Needs: the team names Emma, Erica, Troy and Sophia as active staff with a display name (first name matched).
-- Models are matched by name. Anyone not found is listed in the Messages tab as a NOTICE and skipped.

create or replace function pg_temp.nm(t text) returns text language sql immutable as $f$
  select coalesce(string_agg(x, ' ' order by x), '')
  from unnest(regexp_split_to_array(lower(regexp_replace(trim(coalesce(t, '')), '[^a-zA-Z0-9 ]', '', 'g')), '\s+')) x
$f$;

create or replace function pg_temp.gp_item(org uuid, boss uuid, mid uuid, gp uuid, pa uuid, it jsonb, mem jsonb)
returns text language plpgsql as $f$
declare
  tid uuid; eid uuid; own text; mm uuid; v_model uuid; v_partner uuid; v_vis text; v_meta jsonb; prio text;
  aud text := it->>'a';
begin
  if it->>'k' = 't' then
    if aud = 'partner' and pa is null then return 'skip:nopartner'; end if;
    prio := case when (it->>'h')::boolean then 'high' else 'normal' end;
    v_model := case when aud = 'model' then mid else null end;
    v_partner := case when aud = 'partner' then pa else null end;
    v_vis := case when aud = 'partner' then 'partner_shared' else 'organization' end;
    v_meta := jsonb_build_object('gp_key', it->>'i', 'plan', 'g90', 'task_type', it->>'ty', 'is_hard_stop', (it->>'h')::boolean,
                                 'area', it->>'ar', 'owner_name', it->>'o', 'due_label', it->>'w', 'audience', aud);
    if aud = 'model' then v_meta := v_meta || jsonb_build_object('gameplan_id', gp); end if;
    if it ? 'amt' then v_meta := v_meta || jsonb_build_object('approval_amount', it->'amt'); end if;
    if it ? 'ms' then v_meta := v_meta || jsonb_build_object('models', it->'ms'); end if;
    select id into tid from public.tasks where organization_id = org and metadata->>'gp_key' = it->>'i' limit 1;
    if tid is null then
      insert into public.tasks (organization_id, model_id, partner_agency_id, title, description, priority, due_at, category, status, visibility, created_by, metadata)
      values (org, v_model, v_partner, it->>'t', it->>'d', prio, (it->>'u')::timestamptz, it->>'ty', 'open', v_vis, boss, v_meta)
      returning id into tid;
      if aud = 'model' then
        insert into public.task_assignments (organization_id, task_id, model_id, assignment_role, assigned_by) values (org, tid, mid, 'assignee', boss) on conflict do nothing;
      elsif aud = 'staff' then
        own := lower(split_part(it->>'o', ' ', 1));
        if mem ? own then
          insert into public.task_assignments (organization_id, task_id, member_id, assignment_role, assigned_by) values (org, tid, (mem->>own)::uuid, 'assignee', boss) on conflict do nothing;
        else
          return 'task:nomember:' || own;
        end if;
      end if;
    else
      update public.tasks set title = it->>'t', description = it->>'d', priority = prio, due_at = (it->>'u')::timestamptz, category = it->>'ty',
             metadata = coalesce(metadata, '{}'::jsonb) || v_meta, updated_at = now()
      where id = tid;
    end if;
    return 'task';
  elsif it->>'k' = 'e' then
    v_meta := jsonb_build_object('gp_key', it->>'i', 'plan', 'g90', 'category', it->>'ar', 'event_kind', it->>'ek', 'calendar_event_type', it->>'ty');
    select id into eid from public.events where organization_id = org and metadata->>'gp_key' = it->>'i' limit 1;
    if eid is null then
      insert into public.events (organization_id, title, event_type, status, starts_at, ends_at, timezone, all_day, location, visibility, notes, metadata)
      values (org, it->>'t', it->>'ty', 'scheduled', (it->>'u')::timestamptz, nullif(it->>'en', '')::timestamptz, it->>'z', false, it->>'loc', 'model_shared', it->>'d', v_meta)
      returning id into eid;
    else
      update public.events set title = it->>'t', event_type = it->>'ty', starts_at = (it->>'u')::timestamptz, ends_at = nullif(it->>'en', '')::timestamptz,
             timezone = it->>'z', location = it->>'loc', notes = it->>'d', metadata = coalesce(metadata, '{}'::jsonb) || v_meta, updated_at = now()
      where id = eid;
    end if;
    insert into public.event_models (organization_id, event_id, model_id) values (org, eid, mid) on conflict do nothing;
    return 'event';
  end if;
  return 'skip';
end $f$;

do $gp$
declare
  p jsonb := $json${"models":[{"name":"Adenike Aluko","gp":{"title":"90-Day Gameplan: Nov 8, 2026 to Feb 5, 2027","key_date":"2027-01-19","key_label":"Paris Men's FW27-28","welcome":"Welcome to your 90-day gameplan, Adenike. Every task has a date and a time in your own time zone. Tap Complete when a task is done, or request a new date with a note. Your agent is Erica.","positioning":"Runway: Paris Men's FW27-28 (Tue Jan 19 to Sun Jan 24); Paris Haute Couture SS27 (Mon Jan 25 to Thu Jan 28); Paris Women's FW27-28 (Mon Mar 1 to Tue Mar 9).","market":"Base: Lagos. Shows: Paris Men's FW27-28, Paris Haute Couture SS27, Paris Women's FW27-28.","image_rules":"Test shoots: 2 in this block. Fresh digitals close to your first show. Skin photos four times (Nov 16, Dec 14, pre-show, Feb 1). Nothing is posted or sent without your approval of the selects.","risks":"Schengen visa must be filed by Nov 13 and decided by Dec 21. No decision means a same-day fallback plan. May sign in Milan. Decision Dec 4 changes the visa country and adds a Milan leg (Jan 15 to 19).","cadence":{"daily":"Skin routine morning and night, food and water, sleep 8 hours","walk":"Tuesday and Thursday 30 minutes","weekly":"Sunday wellness check-in with your agent","deadlines":"All dates and times are in your gameplan tasks"}},"ds":{"built":"2026-11-08","until":"2027-02-05","blocks":[{"id":"gp_snack1","days":["0","1","2","3","4","5","6"],"start":"10:30","end":"10:45","title":"Snack + water (fueling plan)","cat":"meal","until":"2027-02-05"},{"id":"gp_snack2","days":["0","1","2","3","4","5","6"],"start":"15:30","end":"15:45","title":"Snack + water (fueling plan)","cat":"meal","until":"2027-02-05"},{"id":"gp_walk","days":["2","4"],"start":"18:00","end":"18:30","title":"Walk practice (gameplan)","cat":"model","until":"2027-02-05"},{"id":"gp_checkin","days":["0"],"start":"17:00","end":"17:20","title":"Sunday wellness check-in with your agent","cat":"routine","until":"2027-02-05"}],"habits":[{"id":"gp_skin","label":"Skin plan from your gameplan: morning and night"},{"id":"gp_fuel","label":"Fueling plan: protein at every meal, two snacks, water"},{"id":"gp_walk","label":"Walk practice Tuesday and Thursday"},{"id":"gp_sleep","label":"Sleep 8 hours"}],"weekly":[{"k":"gp_dates","t":"Open your gameplan: skin photos, walk videos, health checks and test shoots each have a set date and time"},{"k":"gp_walkvid","t":"Walk video due dates: Nov 23, Dec 14 and your pre-show date"}]},"items":[{"i":"g90:adenike-aluko:V1","a":"model","o":"Adenike Aluko","t":"Passport check and scans","d":"Passport valid at least 6 months after your return with 2 blank pages. Upload a clear scan today.","u":"2026-11-10T16:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"Africa/Lagos","w":"Tue Nov 10, 5:00 PM Lagos (Tue Nov 10 11:00 AM ET)"},{"i":"g90:adenike-aluko:PLAN","a":"staff","o":"Erica","t":"Gameplan live for Adenike Aluko","d":"Check that the model sees the gameplan, the mother agency has partner tasks, and the DaySilk events appear.","u":"2026-11-10T17:00:00Z","k":"t","ty":"agent","h":true,"ar":"Gameplan","z":"America/New_York","w":"Tue Nov 10, 12:00 PM ET"},{"i":"g90:adenike-aluko:PA2","a":"partner","o":"Mother agency","t":"Send visa support documents (Adenike Aluko)","d":"Invitation or agency letter and any contract pages needed for the Schengen application.","u":"2026-11-11T17:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"America/New_York","w":"Wed Nov 11, 12:00 PM ET"},{"i":"g90:adenike-aluko:V2","a":"staff","o":"Troy","t":"Visa pack complete for Adenike Aluko","d":"Support letter, accommodation proof, travel insurance, finances, flight reservation, photos.","u":"2026-11-11T17:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"America/New_York","w":"Wed Nov 11, 12:00 PM ET"},{"i":"g90:adenike-aluko:V3e","a":"model","o":"Adenike Aluko","t":"Visa filing day","d":"Visa application and biometrics.","u":"2026-11-13T09:00:00Z","k":"e","ty":"visa","h":false,"ar":"Visa","z":"Africa/Lagos","w":"Fri Nov 13, 10:00 AM Lagos (Fri Nov 13 4:00 AM ET)","en":"2026-11-13T11:00:00Z","loc":null,"ek":"visa appointment"},{"i":"g90:adenike-aluko:G1","a":"model","o":"Adenike Aluko","t":"Confirm your gameplan and shows","d":"Open your gameplan, read the dates, and tap Complete to confirm. Shows: Paris Men's FW27-28, Paris Haute Couture SS27, Paris Women's FW27-28.","u":"2026-11-13T16:00:00Z","k":"t","ty":"agent","h":false,"ar":"Gameplan","z":"Africa/Lagos","w":"Fri Nov 13, 5:00 PM Lagos (Fri Nov 13 11:00 AM ET)"},{"i":"g90:adenike-aluko:V3","a":"model","o":"Adenike Aluko","t":"Visa application filed and biometrics done","d":"Attend your visa centre appointment with every document. Tell your agent the moment it is done.","u":"2026-11-13T16:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Visa","z":"Africa/Lagos","w":"Fri Nov 13, 5:00 PM Lagos (Fri Nov 13 11:00 AM ET)"},{"i":"g90:adenike-aluko:SK1","a":"model","o":"Adenike Aluko","t":"Skin submission #1 (baseline): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Nov 16, 5:00 PM Lagos (Mon Nov 16 11:00 AM ET).","u":"2026-11-16T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Nov 16, 5:00 PM Lagos (Mon Nov 16 11:00 AM ET)"},{"i":"g90:adenike-aluko:SK1e","a":"model","o":"Adenike Aluko","t":"Skin submission #1 due","d":"Upload your skin photos in the portal today.","u":"2026-11-16T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Nov 16, 5:00 PM Lagos (Mon Nov 16 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"},{"i":"g90:adenike-aluko:TS1-team","a":"staff","o":"Erica","t":"Test shoot 1: lock photographer, MUA, stylist and studio (Adenike)","d":"Shoot is Mon Nov 30, 2026, 9:00 AM Lagos at Lagos studio. Book photographer, makeup, hair, stylist and studio, send the mood board to Adenike and the mother agency, and confirm wardrobe. HARD STOP: shoot cannot slip after this time.","u":"2026-11-16T17:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Mon Nov 16, 12:00 PM ET"},{"i":"g90:adenike-aluko:PA1","a":"partner","o":"Mother agency","t":"Confirm representation and show list (Adenike Aluko)","d":"Confirm who represents the model for each market and which shows are approved. If the model is signing in Milan, tell us by Dec 4.","u":"2026-11-18T17:00:00Z","k":"t","ty":"agent","h":false,"ar":"Gameplan","z":"America/New_York","w":"Wed Nov 18, 12:00 PM ET"},{"i":"g90:adenike-aluko:H1","a":"model","o":"Adenike Aluko","t":"Health intake: allergies, food limits, injuries","d":"Fill in the short intake form: allergies, food limits, injuries and anything you want us to plan around. You choose what to share. We never ask for weight or body-measurement targets.","u":"2026-11-20T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Health","z":"Africa/Lagos","w":"Fri Nov 20, 5:00 PM Lagos (Fri Nov 20 11:00 AM ET)"},{"i":"g90:adenike-aluko:SKP","a":"model","o":"Adenike Aluko","t":"Start your skin plan: read and confirm","d":"Every day: AM gentle cleanser, moisturizer, broad-spectrum SPF 30+. PM: remove sunscreen and makeup fully (double cleanse on shoot days), then moisturizer. Once a week: one gentle exfoliation and one hydrating mask. Patch-test anything new on the jaw for 3 days. Never sleep in makeup. If you shave, use a clean blade, shave with the grain and finish with an alcohol-free soother. Climate: heat and humidity. Use a gel or light lotion moisturizer. For breakouts or dark marks after breakouts, ask the reviewer about niacinamide in the morning and azelaic acid at night. Reapply SPF every 2 to 3 hours outdoors and rinse sweat off before it dries. Pre-show protocol (starts 14 days before your first show): no new active products, no peels, lasers, waxing or fillers in the last 7 days, no sunburn or tanning, sleep 8 hours, and remove all makeup at the end of every day. If anything flares, tell your agent the same day. Travel days: cleanse, put on a thick moisturizer, no new products, drink water through the flight, and use a hydrating mask after landing. Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history.","u":"2026-11-23T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Nov 23, 5:00 PM Lagos (Mon Nov 23 11:00 AM ET)"},{"i":"g90:adenike-aluko:WK1","a":"model","o":"Adenike Aluko","t":"Walk video #1: send your 20-second walk","d":"Walk practice, 30 minutes, Tuesday and Thursday. Warm up 5 minutes. Straight-line walk of 10 to 15 steps with level eyes and shoulders back, a clean turn at the end, pause, turn back. Practice in the shoe height you expect to wear. Film one 20-second clip from the front and one from the side, phone at hip height, plain background, full body in frame. Your agent gives written feedback and one drill for the next week. Due Mon Nov 23, 5:00 PM Lagos (Mon Nov 23 11:00 AM ET).","u":"2026-11-23T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Walk","z":"Africa/Lagos","w":"Mon Nov 23, 5:00 PM Lagos (Mon Nov 23 11:00 AM ET)"},{"i":"g90:adenike-aluko:WK1e","a":"model","o":"Adenike Aluko","t":"Walk practice video #1 due","d":"Send your walk video in the portal today.","u":"2026-11-23T16:00:00Z","k":"e","ty":"training","h":false,"ar":"Walk","z":"Africa/Lagos","w":"Mon Nov 23, 5:00 PM Lagos (Mon Nov 23 11:00 AM ET)","en":null,"loc":null,"ek":"walk practice"},{"i":"g90:adenike-aluko:TS1-concept","a":"partner","o":"Mother agency","t":"Approve test shoot 1 concept (Adenike Aluko)","d":"Please approve or comment on the concept and looks for the test shoot on Mon Nov 30, 2026.","u":"2026-11-23T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Mon Nov 23, 12:00 PM ET"},{"i":"g90:adenike-aluko:FUEL","a":"model","o":"Adenike Aluko","t":"Your fueling plan: read it and send allergies or food limits","d":"This is healthy fueling, not dieting. Three meals and two snacks a day, protein at every meal, a vegetable or fruit at most meals, whole grains or starch for energy on training and walk-practice days, and 2 to 3 liters of water. No crash dieting, cleanses, diet pills or skipped meals. MDV does not set weight or measurement targets for any model. If a doctor or dietitian gives you a plan, that plan wins. Tell us any allergies or food limits in your health intake so this plan fits you. Easy local picks: grilled or steamed fish or chicken, beans or moi moi, efo riro or ugu with less oil, boiled or grilled plantain, ofada or brown rice, and fruit like pawpaw, oranges and watermelon. Jollof and fried snacks are fine in smaller portions with a protein beside them. Show weeks: carry snacks (nuts, fruit, a protein bar, a sandwich), eat before every call time, keep water with you, and keep caffeine and alcohol low the night before a casting or show.","u":"2026-11-25T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Diet","z":"Africa/Lagos","w":"Wed Nov 25, 5:00 PM Lagos (Wed Nov 25 11:00 AM ET)"},{"i":"g90:adenike-aluko:PA3","a":"partner","o":"Mother agency","t":"Sign off the gameplan and test shoot plan (Adenike Aluko)","d":"Review the gameplan, test shoot dates and image rules, then approve or comment.","u":"2026-11-25T17:00:00Z","k":"t","ty":"agent","h":false,"ar":"Gameplan","z":"America/New_York","w":"Wed Nov 25, 12:00 PM ET"},{"i":"g90:adenike-aluko:TS1-confirm","a":"model","o":"Adenike Aluko","t":"Confirm your test shoot 1 call sheet","d":"Tap Complete when you have read the call sheet and confirm you can be there at 9:00 AM on Mon Nov 30, 2026. Skin prep: no new products, no waxing, sleep 8 hours.","u":"2026-11-27T16:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Africa/Lagos","w":"Fri Nov 27, 5:00 PM Lagos (Fri Nov 27 11:00 AM ET)"},{"i":"g90:adenike-aluko:TS1-callsheet","a":"staff","o":"Erica","t":"Test shoot 1: send call sheet (Adenike)","d":"Call sheet to Adenike and mother agency: address, call time 9:00 AM Lagos, wardrobe, skin prep and what to eat.","u":"2026-11-27T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Fri Nov 27, 12:00 PM ET"},{"i":"g90:adenike-aluko:TS1","a":"model","o":"Adenike Aluko","t":"Test shoot 1: Adenike","d":"Call time 9:00 AM, wrap about 5:00 PM. Lagos studio. Bring a clean face, hair as discussed, and snacks.","u":"2026-11-30T08:00:00Z","k":"e","ty":"test","h":false,"ar":"Test shoot","z":"Africa/Lagos","w":"Mon Nov 30, 9:00 AM Lagos (Mon Nov 30 3:00 AM ET)","en":"2026-11-30T16:00:00Z","loc":"Lagos studio","ek":""},{"i":"g90:adenike-aluko:V4","a":"staff","o":"Troy","t":"Visa status check #1 (Adenike Aluko)","d":"Check the tracking. If the case is stuck, escalate to Demontez.","u":"2026-12-01T17:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Visa","z":"America/New_York","w":"Tue Dec 1, 12:00 PM ET"},{"i":"g90:adenike-aluko:TS1-selects","a":"staff","o":"Erica","t":"Test shoot 1: send selects (Adenike)","d":"Send the first selects to the model and mother agency for approval.","u":"2026-12-02T22:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Wed Dec 2, 5:00 PM ET"},{"i":"g90:adenike-aluko:TS1-approve","a":"model","o":"Adenike Aluko","t":"Approve your test shoot 1 selects","d":"Pick your favorites and tell your agent what you do not want used. Tap Complete when done.","u":"2026-12-04T16:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Africa/Lagos","w":"Fri Dec 4, 5:00 PM Lagos (Fri Dec 4 11:00 AM ET)"},{"i":"g90:adenike-aluko:TS1-papprove","a":"partner","o":"Mother agency","t":"Approve test shoot 1 selects (Adenike Aluko)","d":"Approve the selects or send notes so the retouch can start.","u":"2026-12-04T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Fri Dec 4, 12:00 PM ET"},{"i":"g90:adenike-aluko:TS2-team","a":"staff","o":"Erica","t":"Test shoot 2: lock photographer, MUA, stylist and studio (Adenike)","d":"Shoot is Fri Dec 18, 2026, 9:00 AM Lagos at Lagos studio. Book photographer, makeup, hair, stylist and studio, send the mood board to Adenike and the mother agency, and confirm wardrobe. HARD STOP: shoot cannot slip after this time.","u":"2026-12-04T17:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Fri Dec 4, 12:00 PM ET"},{"i":"g90:adenike-aluko:TR-offer","a":"staff","o":"Troy","t":"Send travel and stay offer to Adenike Aluko and mother agency","d":"Itinerary: Paris Sun Jan 10 to Mon Mar 15 (Paris Men's, Couture and Women's on one visa). Estimated total $8,019 (flights $1,150, housing $3,520, meals and transport $2,275, transfers $120, visa and insurance $225, 10% contingency). Replace the estimate with real quotes first.","u":"2026-12-07T17:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Travel","z":"America/New_York","w":"Mon Dec 7, 12:00 PM ET"},{"i":"g90:adenike-aluko:TS1-retouch","a":"staff","o":"Erica","t":"Test shoot 1: retouched finals delivered (Adenike)","d":"Retouched finals saved to the model's media in the portal.","u":"2026-12-09T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Wed Dec 9, 5:00 PM ET"},{"i":"g90:adenike-aluko:TR-approve","a":"model","o":"Adenike Aluko","t":"Approve your travel and stay plan: about $8,019","d":"Your season itinerary: Paris Sun Jan 10 to Mon Mar 15 (Paris Men's, Couture and Women's on one visa). Estimated total $8,019: flights $1,150, housing $3,520, meals and local transport $2,275, airport transfers $120, visa and insurance $225, contingency $729. This is an estimate until tickets are booked; final numbers are shown before anything is charged. Tap Complete to approve, or request a change with a note. Due Fri Dec 11, 5:00 PM Lagos (Fri Dec 11 11:00 AM ET).","u":"2026-12-11T16:00:00Z","k":"t","ty":"visa_travel","h":true,"ar":"Travel","z":"Africa/Lagos","w":"Fri Dec 11, 5:00 PM Lagos (Fri Dec 11 11:00 AM ET)","amt":8019},{"i":"g90:adenike-aluko:TR-approve-e","a":"model","o":"Adenike Aluko","t":"Travel plan approval due","d":"Approve the travel and stay estimate (about $8,019).","u":"2026-12-11T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Travel","z":"Africa/Lagos","w":"Fri Dec 11, 5:00 PM Lagos (Fri Dec 11 11:00 AM ET)","en":null,"loc":null,"ek":"travel"},{"i":"g90:adenike-aluko:PA4","a":"partner","o":"Mother agency","t":"Co-sign travel advance and recoup terms (Adenike Aluko)","d":"Estimated travel and stay about $8,019. Please confirm you accept the advance and how it is recouped.","u":"2026-12-11T17:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Travel","z":"America/New_York","w":"Fri Dec 11, 12:00 PM ET"},{"i":"g90:adenike-aluko:TS2-concept","a":"partner","o":"Mother agency","t":"Approve test shoot 2 concept (Adenike Aluko)","d":"Please approve or comment on the concept and looks for the test shoot on Fri Dec 18, 2026.","u":"2026-12-11T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Fri Dec 11, 12:00 PM ET"},{"i":"g90:adenike-aluko:TS1-package","a":"staff","o":"Erica","t":"Test shoot 1: add to book and push the package (Adenike)","d":"Add the images to the book and website, then send the package to clients and mother agencies.","u":"2026-12-11T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Fri Dec 11, 5:00 PM ET"},{"i":"g90:adenike-aluko:SK2","a":"model","o":"Adenike Aluko","t":"Skin submission #2 (progress): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Dec 14, 5:00 PM Lagos (Mon Dec 14 11:00 AM ET).","u":"2026-12-14T16:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Dec 14, 5:00 PM Lagos (Mon Dec 14 11:00 AM ET)"},{"i":"g90:adenike-aluko:SK2e","a":"model","o":"Adenike Aluko","t":"Skin submission #2 due","d":"Upload your skin photos in the portal today.","u":"2026-12-14T16:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Africa/Lagos","w":"Mon Dec 14, 5:00 PM Lagos (Mon Dec 14 11:00 AM ET)","en":null,"loc":null,"ek":"model meeting"},{"i":"g90:adenike-aluko:WK2","a":"model","o":"Adenike Aluko","t":"Walk video #2: send your 20-second walk","d":"Walk practice, 30 minutes, Tuesday and Thursday. Warm up 5 minutes. Straight-line walk of 10 to 15 steps with level eyes and shoulders back, a clean turn at the end, pause, turn back. Practice in the shoe height you expect to wear. Film one 20-second clip from the front and one from the side, phone at hip height, plain background, full body in frame. Your agent gives written feedback and one drill for the next week. Due Mon Dec 14, 5:00 PM Lagos (Mon Dec 14 11:00 AM ET).","u":"2026-12-14T16:00:00Z","k":"t","ty":"training","h":false,"ar":"Walk","z":"Africa/Lagos","w":"Mon Dec 14, 5:00 PM Lagos (Mon Dec 14 11:00 AM ET)"},{"i":"g90:adenike-aluko:WK2e","a":"model","o":"Adenike Aluko","t":"Walk practice video #2 due","d":"Send your walk video in the portal today.","u":"2026-12-14T16:00:00Z","k":"e","ty":"training","h":false,"ar":"Walk","z":"Africa/Lagos","w":"Mon Dec 14, 5:00 PM Lagos (Mon Dec 14 11:00 AM ET)","en":null,"loc":null,"ek":"walk practice"},{"i":"g90:adenike-aluko:TR-fund","a":"staff","o":"Sophia","t":"Release travel advance after approvals (Adenike Aluko)","d":"Only after the model and mother agency approve. Estimated $8,019.","u":"2026-12-14T17:00:00Z","k":"t","ty":"visa_travel","h":false,"ar":"Travel","z":"America/New_York","w":"Mon Dec 14, 12:00 PM ET"},{"i":"g90:adenike-aluko:TS2-callsheet","a":"staff","o":"Erica","t":"Test shoot 2: send call sheet (Adenike)","d":"Call sheet to Adenike and mother agency: address, call time 9:00 AM Lagos, wardrobe, skin prep and what to eat.","u":"2026-12-15T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Tue Dec 15, 12:00 PM ET"},{"i":"g90:adenike-aluko:TS2-confirm","a":"model","o":"Adenike Aluko","t":"Confirm your test shoot 2 call sheet","d":"Tap Complete when you have read the call sheet and confirm you can be there at 9:00 AM on Fri Dec 18, 2026. Skin prep: no new products, no waxing, sleep 8 hours.","u":"2026-12-16T16:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Africa/Lagos","w":"Wed Dec 16, 5:00 PM Lagos (Wed Dec 16 11:00 AM ET)"},{"i":"g90:adenike-aluko:TS2","a":"model","o":"Adenike Aluko","t":"Test shoot 2: Adenike","d":"Call time 9:00 AM, wrap about 5:00 PM. Lagos studio. Bring a clean face, hair as discussed, and snacks.","u":"2026-12-18T08:00:00Z","k":"e","ty":"test","h":false,"ar":"Test shoot","z":"Africa/Lagos","w":"Fri Dec 18, 9:00 AM Lagos (Fri Dec 18 3:00 AM ET)","en":"2026-12-18T16:00:00Z","loc":"Lagos studio","ek":""},{"i":"g90:adenike-aluko:H2","a":"model","o":"Adenike Aluko","t":"Physical exam and bloodwork: done and cleared","d":"Physical exam and bloodwork as your clinician advises (iron, vitamin D, B12 and thyroid are common for travel season), a dental cleaning and a vision check, all by the dates in your gameplan. You choose what to share: MDV only needs 'cleared' or 'not cleared', never your results. Travel health: ask