ouch","a":"staff","o":"Erica","t":"Test shoot 1: retouched finals delivered (Vayla)","d":"Retouched finals saved to the model's media in the portal.","u":"2026-12-22T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Tue Dec 22, 5:00 PM ET"},{"i":"g90:vayla-bovykina:TS1-package","a":"staff","o":"Erica","t":"Test shoot 1: add to book and push the package (Vayla)","d":"Add the images to the book and website, then send the package to clients and mother agencies.","u":"2026-12-28T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Mon Dec 28, 5:00 PM ET"},{"i":"g90:vayla-bovykina:TS2-team","a":"staff","o":"Erica","t":"Test shoot 2: lock photographer, MUA, stylist and studio (Vayla)","d":"Shoot is Thu Jan 14, 2027, 9:00 AM Seoul at Seoul studio. Book photographer, makeup, hair, stylist and studio, send the mood board to Vayla and the mother agency, and confirm wardrobe. HARD STOP: shoot cannot slip after this time.","u":"2026-12-31T17:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Thu Dec 31, 12:00 PM ET"},{"i":"g90:vayla-bovykina:CK1","a":"model","o":"Vayla Bovykina","t":"Mid-season check-in call with your agent","d":"30 minutes: how you feel, sleep, food, skin, walk and travel. Bring questions.","u":"2027-01-06T08:00:00Z","k":"e","ty":"meeting","h":false,"ar":"Health","z":"Asia/Seoul","w":"Wed Jan 6, 5:00 PM Seoul (Wed Jan 6 3:00 AM ET)","en":"2027-01-06T08:30:00Z","loc":null,"ek":"model meeting"},{"i":"g90:vayla-bovykina:TS2-concept","a":"partner","o":"Mother agency","t":"Approve test shoot 2 concept (Vayla Bovykina)","d":"Please approve or comment on the concept and looks for the test shoot on Thu Jan 14, 2027.","u":"2027-01-07T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Thu Jan 7, 12:00 PM ET"},{"i":"g90:vayla-bovykina:SK3","a":"model","o":"Vayla Bovykina","t":"Skin submission #3 (spring): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Jan 11, 5:00 PM Seoul (Mon Jan 11 3:00 AM ET).","u":"2027-01-11T08:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Asia/Seoul","w":"Mon Jan 11, 5:00 PM Seoul (Mon Jan 11 3:00 AM ET)"},{"i":"g90:vayla-bovykina:SK3e","a":"model","o":"Vayla Bovykina","t":"Skin submission #3 due","d":"Upload your skin photos in the portal today.","u":"2027-01-11T08:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Asia/Seoul","w":"Mon Jan 11, 5:00 PM Seoul (Mon Jan 11 3:00 AM ET)","en":null,"loc":null,"ek":"model meeting"},{"i":"g90:vayla-bovykina:TS2-callsheet","a":"staff","o":"Erica","t":"Test shoot 2: send call sheet (Vayla)","d":"Call sheet to Vayla and mother agency: address, call time 9:00 AM Seoul, wardrobe, skin prep and what to eat.","u":"2027-01-11T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Mon Jan 11, 12:00 PM ET"},{"i":"g90:vayla-bovykina:TS2-confirm","a":"model","o":"Vayla Bovykina","t":"Confirm your test shoot 2 call sheet","d":"Tap Complete when you have read the call sheet and confirm you can be there at 9:00 AM on Thu Jan 14, 2027. Skin prep: no new products, no waxing, sleep 8 hours.","u":"2027-01-12T08:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Asia/Seoul","w":"Tue Jan 12, 5:00 PM Seoul (Tue Jan 12 3:00 AM ET)"},{"i":"g90:vayla-bovykina:TS2","a":"model","o":"Vayla Bovykina","t":"Test shoot 2: Vayla","d":"Call time 9:00 AM, wrap about 5:00 PM. Seoul studio. Bring a clean face, hair as discussed, and snacks.","u":"2027-01-14T00:00:00Z","k":"e","ty":"test","h":false,"ar":"Test shoot","z":"Asia/Seoul","w":"Thu Jan 14, 9:00 AM Seoul (Wed Jan 13 7:00 PM ET)","en":"2027-01-14T08:00:00Z","loc":"Seoul studio","ek":""},{"i":"g90:vayla-bovykina:TS2-selects","a":"staff","o":"Erica","t":"Test shoot 2: send selects (Vayla)","d":"Send the first selects to the model and mother agency for approval.","u":"2027-01-18T22:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Mon Jan 18, 5:00 PM ET"},{"i":"g90:vayla-bovykina:TS2-approve","a":"model","o":"Vayla Bovykina","t":"Approve your test shoot 2 selects","d":"Pick your favorites and tell your agent what you do not want used. Tap Complete when done.","u":"2027-01-20T08:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"Asia/Seoul","w":"Wed Jan 20, 5:00 PM Seoul (Wed Jan 20 3:00 AM ET)"},{"i":"g90:vayla-bovykina:TS2-papprove","a":"partner","o":"Mother agency","t":"Approve test shoot 2 selects (Vayla Bovykina)","d":"Approve the selects or send notes so the retouch can start.","u":"2027-01-20T17:00:00Z","k":"t","ty":"testing","h":false,"ar":"Test shoot","z":"America/New_York","w":"Wed Jan 20, 12:00 PM ET"},{"i":"g90:vayla-bovykina:TS2-retouch","a":"staff","o":"Erica","t":"Test shoot 2: retouched finals delivered (Vayla)","d":"Retouched finals saved to the model's media in the portal.","u":"2027-01-25T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Mon Jan 25, 5:00 PM ET"},{"i":"g90:vayla-bovykina:TS2-package","a":"staff","o":"Erica","t":"Test shoot 2: add to book and push the package (Vayla)","d":"Add the images to the book and website, then send the package to clients and mother agencies.","u":"2027-01-27T22:00:00Z","k":"t","ty":"testing","h":true,"ar":"Test shoot","z":"America/New_York","w":"Wed Jan 27, 5:00 PM ET"},{"i":"g90:vayla-bovykina:SK4","a":"model","o":"Vayla Bovykina","t":"Skin submission #4 (check): photos due","d":"Skin submission = 4 photos in daylight by a window, no makeup, no filter, no retouching: front, left, right, and a close-up of any area you want help with. Add three lines: skin type as you see it, any concerns, and any product reaction. A licensed skin professional reviews it. You can choose to share only the photos and not any medical history. Due Mon Feb 1, 5:00 PM Seoul (Mon Feb 1 3:00 AM ET).","u":"2027-02-01T08:00:00Z","k":"t","ty":"progress_submission","h":false,"ar":"Skin","z":"Asia/Seoul","w":"Mon Feb 1, 5:00 PM Seoul (Mon Feb 1 3:00 AM ET)"},{"i":"g90:vayla-bovykina:SK4e","a":"model","o":"Vayla Bovykina","t":"Skin submission #4 due","d":"Upload your skin photos in the portal today.","u":"2027-02-01T08:00:00Z","k":"e","ty":"deadline","h":false,"ar":"Skin","z":"Asia/Seoul","w":"Mon Feb 1, 5:00 PM Seoul (Mon Feb 1 3:00 AM ET)","en":null,"loc":null,"ek":"model meeting"}]}]}$json$;
  org uuid; boss uuid; mem jsonb := '{}'::jsonb;
  m jsonb; it jsonb; mid uuid; gp uuid; dp uuid; pa uuid; st text; r text;
  n_models int := 0; n_task int := 0; n_event int := 0; n_skip int := 0;
  miss text := ''; nomem text := ''; pmeta jsonb; ppfound boolean; n_ds int := 0;
begin
  select id into org from public.organizations where slug = 'maison-de-veux';
  if org is null then raise exception 'Organization maison-de-veux was not found'; end if;
  select id into boss from auth.users where lower(email) = 'demontez@maisondeveux.com';
  select coalesce(jsonb_object_agg(k, v), '{}'::jsonb) into mem from (
    select lower(split_part(pr.display_name, ' ', 1)) k, om.id::text v
    from public.organization_members om join public.profiles pr on pr.user_id = om.user_id
    where om.organization_id = org and om.member_type = 'staff' and om.status = 'active') s;

  for m in select * from jsonb_array_elements(p->'models') loop
    select id into mid from public.models where organization_id = org and pg_temp.nm(display_name) = pg_temp.nm(m->>'name') limit 1;
    if mid is null then miss := miss || (m->>'name') || '; '; continue; end if;
    n_models := n_models + 1;

    select id, development_plan_id, status into gp, dp, st from public.model_gameplans where organization_id = org and model_id = mid limit 1;
    if gp is null then
      insert into public.model_gameplans (organization_id, model_id, status, title, key_date, key_date_label, welcome_message, brand_positioning, market_focus, image_rules, risks, checkin_cadence, created_by)
      values (org, mid, 'active', m->'gp'->>'title', (m->'gp'->>'key_date')::date, m->'gp'->>'key_label', m->'gp'->>'welcome', m->'gp'->>'positioning',
              m->'gp'->>'market', m->'gp'->>'image_rules', m->'gp'->>'risks', m->'gp'->'cadence', boss)
      returning id into gp;
      dp := null;
    else
      update public.model_gameplans set status = 'active',
             title = coalesce(title, m->'gp'->>'title'), key_date = coalesce(key_date, (m->'gp'->>'key_date')::date),
             key_date_label = coalesce(key_date_label, m->'gp'->>'key_label'), welcome_message = coalesce(welcome_message, m->'gp'->>'welcome'),
             brand_positioning = coalesce(brand_positioning, m->'gp'->>'positioning'), market_focus = coalesce(market_focus, m->'gp'->>'market'),
             image_rules = coalesce(image_rules, m->'gp'->>'image_rules'), risks = coalesce(risks, m->'gp'->>'risks'), updated_at = now()
      where id = gp;
    end if;
    if dp is null then
      insert into public.development_plans (organization_id, model_id, title, status, starts_on, target_date, summary, metadata)
      values (org, mid, m->'gp'->>'title', 'active', date '2026-11-08', (m->'gp'->>'key_date')::date, m->'gp'->>'positioning',
              jsonb_build_object('source', 'smart_gameplan', 'gameplan_id', gp, 'plan', 'g90'))
      returning id into dp;
      update public.model_gameplans set development_plan_id = dp where id = gp;
    end if;

    -- daily routine blocks, habits and weekly items for the model's own DaySilk (kept beside their plan, so re-saving their answers never removes them)
    -- model_private_profiles has no id column: a row is identified by organization_id + model_id
    select metadata into pmeta from public.model_private_profiles where organization_id = org and model_id = mid limit 1;
    ppfound := found;
    pmeta := jsonb_set(coalesce(pmeta, '{}'::jsonb), '{daysilk}', coalesce(pmeta->'daysilk', '{}'::jsonb) || jsonb_build_object('gameplan', m->'ds'), true);
    if not ppfound then
      insert into public.model_private_profiles (organization_id, model_id, metadata) values (org, mid, pmeta);
    else
      update public.model_private_profiles set metadata = pmeta where organization_id = org and model_id = mid;
    end if;
    n_ds := n_ds + 1;

    select partner_agency_id into pa from public.model_placements
      where organization_id = org and model_id = mid and status in ('active', 'pending', 'placed') order by created_at desc limit 1;

    for it in select * from jsonb_array_elements(m->'items') loop
      r := pg_temp.gp_item(org, boss, mid, gp, pa, it, mem);
      if r = 'task' then n_task := n_task + 1;
      elsif r = 'event' then n_event := n_event + 1;
      elsif r like 'task:nomember:%' then n_task := n_task + 1; nomem := nomem || substr(r, 15) || ' ';
      else n_skip := n_skip + 1; end if;
    end loop;
  end loop;

  raise notice 'Models loaded: %. Tasks: %. Calendar events: %. DaySilk routine blocks written for: %. Skipped (no mother agency placement on file): %.', n_models, n_task, n_event, n_ds, n_skip;
  if miss <> '' then raise notice 'Models NOT found by name (fix the name in Models and run again): %', miss; end if;
  if nomem <> '' then raise notice 'Team names with no matching active staff (first names): %', (select string_agg(distinct x, ', ') from unnest(string_to_array(trim(nomem), ' ')) x); end if;
end $gp$;
